"""The human-readable attestation report, generated from spec + state.

The engine's own state (`.attest/state.json`) is a machine contract: ephemeral,
gitignored, regenerated every run. This is the other artifact -- committed,
reviewed in PRs, and the thing a person or an auditor actually reads. It is
generated and golden-checked, never hand-edited, so it cannot drift from the
verdicts it reports.

It exists because "no bookkeeping" is the wrong lesson to take from replacing a
hand-maintained registry. What was worth removing was the *hand-maintained*
part; the evidence is worth keeping. A report nobody can read is not evidence.

Two columns carry the honesty. **Verdict** distinguishes a computed pass from
an unjudged claim -- `verified` was measured, `unsupported` was not. **Scope**
says how strong a pass is: `test` means the annotated test killed the mutants,
`package` means some test in the package did (see mutator.py). Collapsing
those into a single tick is exactly the false assurance this method exists to
prevent.
"""

from __future__ import annotations

MARK = {
    "verified": "verified",
    "behavioral": "behavioral",
    "vacuous": "**VACUOUS**",
    "broken": "**broken**",
    "missing_target": "**missing target**",
    "no_mutants": "**no mutants**",
    "error": "**error**",
    "skipped": "**skipped**",
    "unsupported": "not judged here",
    "unstamped": "not stamped",
    "survivors": "package survivors",
}

HEADER = """# Attestation coverage

> Generated by `attest report --update`. Do not edit by hand -- it is a golden
> file, and a hand-edited verdict is a verdict nobody computed.

"""


def _cell(s) -> str:
    """Escape a table cell. A pipe in a description silently breaks the row."""
    return str(s).replace("|", "\\|") if s is not None else "-"


def _claim_row(claim: dict, annotations: list[dict] | None, verdict: dict | None) -> str:
    if annotations:
        tests = [a.get("test") for a in annotations if a.get("test")]
        guards = [a.get("mutates") for a in annotations if a.get("mutates")]
        test_str = ", ".join(f"`{t}`" for t in tests) if tests else "-"
        guard_str = ", ".join(f"`{g}`" for g in sorted(set(guards))) if guards else "-"
    else:
        test_str, guard_str = "-", "-"
    if claim.get("status") == "pending":
        state, scope = "pending", ""
        blocking = claim.get("blocking") or "no blocking task named"
        detail = f"blocked on: {blocking}"
    elif verdict is None:
        state, scope, detail = (
            "not run",
            "",
            "no recorded `attest check --record` run has judged this claim",
        )
    else:
        state = MARK.get(verdict["status"], verdict["status"])
        scope = verdict.get("scope") or ""
        survivors = verdict.get("survivors")
        detail = "; ".join(survivors) if survivors else (verdict.get("detail") or "")
    return "| {} | {} | {} | {} | {} | {} | {} |".format(
        _cell(claim["id"]),
        _cell(claim.get("description")),
        _cell(claim.get("basis", "test")),
        test_str,
        guard_str,
        f"{state} ({scope})" if scope else state,
        _cell(detail) if detail else "-",
    )


def render(spec: dict, state: dict, record: dict | None = None) -> str:
    """Render the committed report from spec + a fresh scan + the RECORD.

    Verdicts come only from the committed record — never from ephemeral
    state — so the same repo renders the same report on every machine: CI
    can golden-check a report whose mutation runs it could never afford to
    repeat, and the run's age is stated as a date instead of hidden as
    implied freshness (the audit chain's verify -record pattern).
    """
    claims = spec.get("claims", [])
    derived = state.get("derived", {})
    mutation = (record or {}).get("mutation", {})

    # Counts computed here from spec + record, for the same reason the
    # verdicts are: state["summary"] is whatever the last local command
    # left behind, and a golden must not depend on it.
    active = [c for c in claims if c.get("status") == "active"]
    n = {
        "total": len(claims),
        "pending": sum(1 for c in claims if c.get("status") == "pending"),
        "verified": sum(1 for c in active if mutation.get(c["id"], {}).get("status") == "verified"),
        "behavioral": sum(1 for c in active if mutation.get(c["id"], {}).get("status") == "behavioral"),
        "vacuous": sum(1 for c in active if mutation.get(c["id"], {}).get("status") == "vacuous"),
        "broken": sum(
            1
            for c in active
            if mutation.get(c["id"], {}).get("status")
            in ("broken", "missing_target", "no_mutants", "error", "skipped")
        ),
        "unsupported": sum(1 for c in active if mutation.get(c["id"], {}).get("status") == "unsupported"),
        "unstamped": sum(1 for c in active if mutation.get(c["id"], {}).get("status") == "unstamped"),
        "survivors": sum(1 for c in active if mutation.get(c["id"], {}).get("status") == "survivors"),
        "unrecorded": sum(1 for c in active if c["id"] not in mutation),
    }

    lines = [HEADER.rstrip("\n"), ""]
    if record:
        lines.append(
            "**Mutation verdicts recorded {at} by `attest check --record`.** "
            "The date is part of the claim: verdicts age from that run, and "
            "a reader weighs them accordingly.".format(
                at=record.get("recordedAt", "at an unrecorded time")
            )
        )
    else:
        lines.append(
            "**No mutation record.** The bindings below are current (derived "
            "from a fresh scan); the verdict column awaits the first "
            "`attest check --record` run."
        )
    lines.append("")
    lines.append(
        "**{total} claims: {verified} verified, {behavioral} behavioral, "
        "{vacuous} vacuous, {broken} broken, "
        "{unsupported} not judged, {unstamped} not stamped, {survivors} with "
        "unattributed package survivors, {unrecorded} not in the record, "
        "{pending} pending.**".format(**n)
    )
    if n["behavioral"]:
        lines.append("")
        lines.append(
            "> *Behavioral* claims are discharged by their bound test passing; "
            "mutation is not applicable to the property (the rationale column "
            "says why). They are counted apart from *verified* because the "
            "assurance is of a different kind, not a lesser amount of the "
            "same kind."
        )
    lines.append("")
    if n["unsupported"] or n["unstamped"]:
        lines.append(
            "> Claims marked *not judged here* are bound to a test but have no "
            "mutation engine on this platform; *not stamped* means no "
            "`mutates=` target declares the guarded surface yet. Both are "
            "counted separately rather than folded into the pass column, "
            "because an unjudged claim is a gap, not a verdict."
        )
        lines.append("")
    lines.append("| Claim | Description | Basis | Test | Guards | Verdict | Detail |")
    lines.append("|---|---|---|---|---|---|---|")
    for claim in sorted(claims, key=lambda c: c["id"]):
        lines.append(
            _claim_row(claim, derived.get(claim["id"]), mutation.get(claim["id"]))
        )
    return "\n".join(lines) + "\n"
